<?php require_once __DIR__.'/../includes/user-check.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['nama']??'');if($name!==''){$q=$pdo->prepare('UPDATE users SET nama=? WHERE id=?');$q->execute([$name,$_SESSION['user']['id']]);$_SESSION['user']['nama']=$name;log_activity($pdo,(int)$_SESSION['user']['id'],'Ubah profil');$msg='Profil diperbarui.';}}$pageTitle='Profil';require __DIR__.'/../includes/header.php';?><h1>Profil</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif?><form method="post" class="card form"><?=csrf_field()?><label>Nama<input name="nama" value="<?=e($_SESSION['user']['nama'])?>" required></label><label>Email<input value="<?=e($_SESSION['user']['email'])?>" disabled></label><button class="button">Simpan</button></form><?php require __DIR__.'/../includes/footer.php';?>